import * as THREE from 'three';
import {GLTFLoader} from 'https://cdn.jsdelivr.net/npm/three@0.180.0/examples/jsm/loaders/GLTFLoader.js';

// Kenney City Kit Roads — CC0. The user's previously supplied road-straight GLB
// is embedded here so the game does not depend on another host for the road kit.
const ROAD_STRAIGHT='data:model/gltf-binary;base64,';

const loader=new GLTFLoader();
let templatePromise=null;
function template(){
  if(!templatePromise)templatePromise=new Promise((resolve,reject)=>loader.load(ROAD_STRAIGHT,g=>resolve(g.scene),undefined,reject));
  return templatePromise;
}

function nodeMap(level){return new Map((level?.network?.nodes||[]).map(n=>[n.id,n]));}

function brightenRoad(root,wet=false){
  root.traverse(o=>{
    if(!o.isMesh)return;
    o.receiveShadow=true;
    o.castShadow=false;
    const mats=Array.isArray(o.material)?o.material:[o.material];
    const cloned=mats.map(m=>{
      if(!m)return m;
      const q=m.clone();
      if('roughness' in q)q.roughness=wet?.34:.78;
      if('metalness' in q)q.metalness=wet?.12:.02;
      return q;
    });
    o.material=Array.isArray(o.material)?cloned:cloned[0];
  });
}

export async function addKenneyRoadOverlay(level,world){
  const token=(world.userData.kenneyRoadToken||0)+1;
  world.userData.kenneyRoadToken=token;
  try{
    const src=await template();
    if(world.userData.kenneyRoadToken!==token)return;
    const map=nodeMap(level),wet=level?.weather==='rain';
    for(const e of level?.network?.edges||[]){
      const a=map.get(e.a),b=map.get(e.b);if(!a||!b)continue;
      const dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz);if(len<.1)continue;
      const count=Math.max(1,Math.ceil(len/8.6)),tileLen=len/count,ang=Math.atan2(dx,dz);
      for(let i=0;i<count;i++){
        const t=(i+.5)/count;
        const g=src.clone(true);
        brightenRoad(g,wet);
        g.name='kenney-road-overlay';
        g.position.set(a.x+dx*t,.165,a.z+dz*t);
        g.rotation.y=ang;
        g.scale.set(10.7,1,tileLen+0.05);
        world.add(g);
      }
    }
  }catch(err){console.warn('Kenney road overlay unavailable; keeping procedural roads.',err);}
}
